<?php
$tp = sms_templates(); $h = '<form class="form" data-api="sms_tpl_save"><table class="tbl"><tr><th>کلید</th><th>کاربرد</th><th>پارامترها</th><th>شناسهٔ قالب در SMS.IR</th><th>خاموش</th></tr>';
foreach (sms_tpl_catalog() as $k => [$t, $ps, $ex]) $h .= '<tr><td><code>' . h($k) . '</code></td><td>' . h($t) . '</td><td><code>' . h(implode(', ', $ps)) . '</code></td><td><input name="tpl[' . h($k) . ']" value="' . h($tp[$k]['id'] ?? '') . '" dir="ltr" style="width:120px"></td><td><input type="checkbox" name="off[' . h($k) . ']" value="1"' . (isset($tp[$k]) && empty($tp[$k]['on']) ? ' checked' : '') . '></td></tr>';
echo ui_card('قالب‌های پیامک (فقط قالب؛ هیچ پیامکی بدونِ قالب نمی‌رود)', $h . '</table><div class="actions"><button class="btn primary">ذخیره</button></div></form><p class="muted">قالبِ «otp» برای پرشدنِ خودکار در اندروید باید خطِ آخرش دقیقاً «@' . h(otp_webotp_host()) . ' #VERIFICATIONCODE#» (پارامترِ VERIFICATIONCODE خودش «#کد» است) باشد. هر پارامتر حداکثر ۲۵ نویسه.</p>');
echo ui_card('اتصال', ui_form('settings_save', ['smsir_api_key' => ['کلیدِ API (خالی = بی‌تغییر)', 'password'], 'sms_test_mode' => ['حالتِ آزمایشی (ارسال نمی‌شود، فقط ثبت)', 'select', 1, ['1' => 'روشن', '0' => 'خاموش']], 'sms_retry_max' => ['سقفِ تلاشِ دوباره', 'int']], ['sms_test_mode' => setting('sms_test_mode', '1'), 'sms_retry_max' => setting('sms_retry_max', 3)])
    . '<p>کلید: ' . (setting('smsir_api_key') ? ui_badge('ثبت شده', 'ok') : ui_badge('ثبت نشده', 'err')) . '</p>'
    . ui_form('sms_test', ['mobile' => ['موبایل', 'text', 1], 'key' => ['قالب', 'select', 1, array_map(fn($c) => $c[0], sms_tpl_catalog())], 'params[CODE]' => ['CODE (برای آزمون)', 'text', 0, [], '12345']], [], ['submit' => 'ارسالِ آزمایشی', 'then' => 'reload']));
echo ui_card('دفترِ پیامک', ui_table(['at' => ['زمان', 'datetime'], 'mobile' => ['شماره', 'num'], 'kind' => 'نوع', 'tpl_key' => 'قالب', 'ref' => ['مرجع', fn($r) => h(($r['ref_type'] ?? '') . ' ' . ($r['ref_id'] ?? ''))], 'ok' => ['نتیجه', fn($r) => $r['ok'] ? ui_badge('رفت', 'ok') : ui_badge('نرفت', 'err')], 'msg' => 'پیام', 'tries' => ['تلاش', 'num'],
    'a' => ['', fn($r) => !$r['ok'] && $r['kind'] !== 'otp' && $r['tries'] < sms_retry_max() ? ui_btn_api('ارسالِ دوباره', 'sms_retry', ['id' => $r['id']], ['class' => 'sm']) : '']], rows("SELECT * FROM sms_log ORDER BY id DESC LIMIT 200"), ['filter' => 1]));
